const NACH_ID = new Map(POOL.map(f => [f.id, f]));

// Fotos, die als Karte taugen, aber nicht gross als Titelbild: Showroom oder
// Haendler-Schild mit Herstellerlogo im Hintergrund.
export const NICHT_ALS_TITEL = new Set([
  'mitsubishi-asx-1-0-turbo-plus', 'citroen-c3-aircross-puretech-110', 'toyota-c-hr-1-8-hybrid-flow',
  'cupra-leon-sportstourer-1-5-etsi', 'volkswagen-passat-variant-2-0-tdi-business', 'skoda-fabia-1-0-tsi-style',
]);

// Schreibweisen aus OSM/Google auf die Namen im Pool.
const ALIAS = {
  vw: 'Volkswagen', volkswagen: 'Volkswagen', mercedes: 'Mercedes-Benz', 'mercedes-benz': 'Mercedes-Benz', 'mercedes benz': 'Mercedes-Benz',
  skoda: 'Škoda', 'škoda': 'Škoda', seat: 'Seat', citroen: 'Citroën', 'citroën': 'Citroën', mini: 'Mini', bmw: 'BMW', audi: 'Audi',
  ford: 'Ford', opel: 'Opel', toyota: 'Toyota', mitsubishi: 'Mitsubishi', renault: 'Renault', mazda: 'Mazda', nissan: 'Nissan', kia: 'Kia',
  fiat: 'Fiat', volvo: 'Volvo', honda: 'Honda', peugeot: 'Peugeot', dacia: 'Dacia', hyundai: 'Hyundai', suzuki: 'Suzuki', subaru: 'Subaru',
  jeep: 'Jeep', cupra: 'Cupra', porsche: 'Porsche',
};
export const markeNormal = m => ALIAS[String(m || '').trim().toLowerCase()] || null;
export const POOL_MARKEN = [...new Set(POOL.map(f => f.marke))];

// Fuer Haendler ohne feste Marke: was auf Gebrauchtwagen-Hoefen typisch steht.
const GEMISCHT = ['volkswagen-golf-1-5-etsi-life', 'skoda-octavia-2-0-tdi-style', 'ford-focus-1-0-ecoboost-titanium', 'bmw-118i-advantage',
  'audi-a4-avant-35-tdi-s-line', 'renault-clio-tce-90-evolution', 'volkswagen-t-roc-1-5-tsi-style', 'hyundai-tucson-1-6-t-gdi-hybrid',
  'mercedes-benz-a-180-progressive', 'opel-mokka-1-2-turbo-elegance', 'seat-ibiza-1-0-tsi-fr', 'kia-sportage-1-6-t-gdi-vision',
  'toyota-rav4-2-5-hybrid-comfort', 'dacia-duster-tce-130-prestige', 'volkswagen-tiguan-2-0-tdi-elegance', 'mazda-cx-5-skyactiv-g-165-advantage'];

// Kleiner, fester Zufall: dieselbe Zahl ergibt immer dieselbe Auswahl.
function zufall(seed) {
  let s = (seed >>> 0) || 1;
  return () => { s ^= s << 13; s >>>= 0; s ^= s >> 17; s ^= s << 5; s >>>= 0; return s / 4294967296; };
}

// ids der Fahrzeuge fuer einen Betrieb: erst seine Marken, dann gemischt.
export function fahrzeugeWaehlen(marken, anzahl = 6, seed = 1) {
  const r = zufall(seed);
  const mischen = a => a.map(x => [r(), x]).sort((p, q) => p[0] - q[0]).map(p => p[1]);
  const eigene = [...new Set((marken || []).map(markeNormal).filter(Boolean))];
  // Mehrere Marken: abwechselnd ziehen, damit jede vorkommt.
  const stapel = eigene.map(m => mischen(POOL.filter(f => f.marke === m)));
  const wahl = [];
  while (wahl.length < anzahl && stapel.some(s => s.length)) for (const s of stapel) if (s.length && wahl.length < anzahl) wahl.push(s.shift());
  for (const id of mischen(GEMISCHT)) {
    if (wahl.length >= anzahl) break;
    const f = NACH_ID.get(id);
    if (f && !wahl.includes(f) && !eigene.length) wahl.push(f);
  }
  // Marken-Haendler mit wenig Pool-Modellen: auffuellen mit gemischten.
  for (const id of mischen(GEMISCHT)) { if (wahl.length >= anzahl) break; const f = NACH_ID.get(id); if (f && !wahl.includes(f)) wahl.push(f); }
  return wahl;
}

// Anzeige-Daten: Erstzulassung, Kilometer und Preis je Fahrzeug und Betrieb
// leicht verschieden, damit nicht jede Vorschau dieselben Zahlen zeigt.
export function fahrzeugAnzeige(id, seed = 1) {
  const f = NACH_ID.get(id);
  if (!f) return null;
  let h = seed;
  for (const c of id) h = (h * 31 + c.charCodeAt(0)) >>> 0;
  const jahr = 2020 + (h % 4);
  const km = 12000 + ((h >>> 3) % 9) * 7500 + (jahr === 2023 ? -8000 : 0);
  const faktor = 1 + (jahr - 2021) * 0.08 - (km - 40000) / 400000;
  const preis = Math.max(5990, Math.round(f.preis * faktor / 100) * 100 - 10);
  const monat = String(1 + ((h >>> 7) % 12)).padStart(2, '0');
  return { ...f, ez: `${monat}/${jahr}`, km: Math.max(4500, km), preis, bild: `/bilder/vorschau/${f.id}.jpg` };
}
